import highlight from 'flarum/common/helpers/highlight';
import Avatar from 'flarum/common/components/Avatar';
import username from 'flarum/common/helpers/username';
export default class UserSearchSource {
  view(query) {
    if (query.length < 3 || this.loading) return;
    app.cache.conversationResults ??= [];
    this.query = query;
    if (!app.cache.conversationResults[this.query]) {
      this.loading = true;
      app.cache.conversationResults[this.query] = [];
      app.store.find('users', {
        filter: {
          q: this.query
        },
        page: {
          limit: 5
        }
      }).then(this.pushResults.bind(this));
    } else return [m("li", {
      className: "Dropdown-header"
    }, app.translator.trans('core.forum.search.users_heading')), app.cache.conversationResults[this.query].map(user => {
      let name = username(user);
      name = highlight(name.text, this.query);
      return m("li", {
        className: "SearchResult",
        "data-index": user.id()
      }, m("a", {
        "data-index": 'users:' + user.id()
      }, m(Avatar, {
        user: user
      }), name));
    })];
  }
  pushResults(results) {
    results.payload.data.map(result => {
      const user = app.store.getById('users', result.id);
      if (parseInt(user.id()) !== parseInt(app.session.user.id())) {
        app.cache.conversationResults[this.query].push(user);
      }
    });
    this.loading = false;
    m.redraw();
  }
}
flarum.reg.add('flatrate-private-messages-bridge', 'forum/components/UserSearchSource', UserSearchSource);